	static void N_whHookWeapons5(FCtx& C)
	{
		// whHookWeapons5 : K2Node_CallFunction DrawWeapons
		UObject* v_whHookPawn1_ReturnValue{};
		v_whHookPawn1_ReturnValue = UGameplayStatics::GetPlayerPawn(C.Self, 0);
		AActor* tg_whHookKit2 = Cast<AActor>(v_whHookPawn1_ReturnValue);
		UObject* v_whHookKit2_ReturnValue{};
		if (tg_whHookKit2) { v_whHookKit2_ReturnValue = tg_whHookKit2->GetComponentByClass(CDGEN_CLASS("/Game/CastleDefender/Gameplay/Castle/BPC_WeaponKit.BPC_WeaponKit_C")); }
		// HAND EDIT 11-06 #446 (owner): the WEAPONSMITH list is the WEAPONS tab (Tab 0) of Vesna's trade, but it drew on top of the
		// other tabs too. While the trade is open (MPC_SkillTree.Trade.R > 0) on another tab, skip the list and the perk card.
		// cd.Shop.WeaponsmithAlways 1 = old behaviour. (re-add after a regeneration)
		{
			static int32 GWeaponsmithAlways = 0;
			static FAutoConsoleVariableRef CVarWeaponsmithAlways(TEXT("cd.Shop.WeaponsmithAlways"), GWeaponsmithAlways, TEXT("1 = the WEAPONSMITH list draws on every Vesna tab (old behaviour)."));
			UObject* TradeComp = tg_whHookKit2 ? tg_whHookKit2->GetComponentByClass(CDGEN_CLASS("/Game/CastleDefender/Gameplay/Castle/BPC_VesnaTrade.BPC_VesnaTrade_C")) : nullptr;
			if (!GWeaponsmithAlways && TradeComp)
			{
				const FLinearColor TradeV = UKismetMaterialLibrary::GetVectorParameterValue(C.Self, CDGEN_ASSET(UMaterialParameterCollection, "/Game/CastleDefender/UI/SkillTree/MPC_SkillTree.MPC_SkillTree"), CDGEN_NAME("Trade"));
				const FIntProperty* TabProp = FindFProperty<FIntProperty>(TradeComp->GetClass(), TEXT("Tab"));
				if (TradeV.R > 0.5f && TabProp && TabProp->GetPropertyValue_InContainer(TradeComp) != 0) { return; }
			}
		}
		int32 v_WeaponSizeX_ReturnValue{};
		v_WeaponSizeX_ReturnValue = UKismetMathLibrary::Add_IntInt(C.S.o_CX_1_SizeX, 1);
		int32 v_WeaponSizeY_ReturnValue{};
		v_WeaponSizeY_ReturnValue = UKismetMathLibrary::Add_IntInt(C.S.o_CX_1_SizeY, 1);
		{ CDGen::FCall Call(fs_whHookWeapons5, v_whHookKit2_ReturnValue, CDGEN_NAME("DrawWeapons"), nullptr);
		  if (Call.Ok()) {
		    Call.Set<UObject*>(CDGEN_NAME("Hud"), C.Self);
		    Call.Set<int32>(CDGEN_NAME("SizeX"), v_WeaponSizeX_ReturnValue);
		    Call.Set<int32>(CDGEN_NAME("SizeY"), v_WeaponSizeY_ReturnValue);
		    Call.Invoke();
		  } }
		UCDWeaponPerks::DrawShopCard(C.Self, v_WeaponSizeX_ReturnValue, v_WeaponSizeY_ReturnValue);   // HAND EDIT 11-06 weapons: perk card right of the list (re-add after a regeneration)
	}

